PREFIX dbo: <http://dbpedia.org/ontology/> 
PREFIX res: <http://dbpedia.org/resource/> 
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?uri 
WHERE { 
  ?uri rdf:type dbo:Mountain ; 
  dbo:locatedInArea ?area ;
  dbo:maximumElevation ?elevation .
  ?area dbo:country res:Germany 
} 
ORDER BY DESC(?elevation) 
LIMIT 1

```sparql
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT DISTINCT ?president ?presidentName
WHERE {
  ?president a dbo:President ;
             dbo:country res:United_States_of_America ;
             dbo:termStart ?start ;
             dbo:termEnd ?end .
  res:Vietnam_War dbp:date ?warDate .
  FILTER (?start <= ?warDate && ?warDate <= ?end)
  ?president rdfs:label ?presidentName .
  FILTER (LANG(?presidentName) = "en")
}
```

