PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>

SELECT ?program (COUNT(?airline) AS ?count)
WHERE {
  ?airline a dbo:Airline ;
           dbo:alliance ?program .
}
GROUP BY ?program
ORDER BY DESC(?count)
LIMIT 1

