PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?uri
WHERE {
  ?cave rdf:type dbo:Cave ;
        dbo:locatedInArea/dbo:country ?uri .
  ?uri rdf:type dbo:Country .
}
GROUP BY ?uri
HAVING (COUNT(?cave) > 2)

